def gen(rng):
    def fmt(n, piles):
        return f"{n} {len(piles)}\n" + ' '.join(map(str, piles))
    tests = [fmt(1, [5]), fmt(1, [3, 9, 4]), fmt(3, [1, 1, 1]), fmt(2, [10**6, 1]), fmt(4, [8, 3, 6, 5]), fmt(3, [4, 2, 7, 3, 5, 1])]
    for m in (2, 3, 4, 5, 6, 8, 10, 12):
        for _ in range(3):
            n = rng.randint(1, m)
            tests.append(fmt(n, [rng.randint(1, 12) for _ in range(m)]))
    M = 10**5
    tests.append(fmt(5000, [rng.randint(1, 10**6) for _ in range(M)]))
    tests.append(fmt(1, [rng.randint(1, 10**6) for _ in range(M)]))
    tests.append(fmt(M, [rng.randint(1, 10**6) for _ in range(M)]))
    tests.append(fmt(M // 2, [rng.randint(1, 10**6) for _ in range(M)]))
    tests.append(fmt(30, [10**6] * M))
    return tests

